import React, { createContext, useContext, useReducer } from 'react'
import reducer, { INITIAL_STATE } from '../state/reducer'

export const RecipientContext = createContext()

export const RecipientContextProvider = (props) => {
  return (
    <RecipientContext.Provider value={useReducer(reducer, INITIAL_STATE)}>
      {props.children}
    </RecipientContext.Provider>
  )
}

export const useRecipientContextValue = () => useContext(RecipientContext)
