/* eslint-disable react-hooks/exhaustive-deps */
import React, { useState, useEffect, useCallback } from 'react'
import { notification } from 'antd'
import fileDownload from 'js-file-download'
import QueryString from 'query-string'

import {
  useLoaderContextValue,
  useErrorContextValue,
  resetError
} from '@pasarpolis/common-react-hooks'

import CommonTable from './recipientsTable'
import Modal from './addRecipientsModal'
import {
  useGetRecipients,
  useGetNotificationType,
  useAddRecipients,
  useRemoveRecipients,
  useResetState,
  useImportRecipients,
  useExportRecipients
} from '../state/hooks/useRecipientsContext'

export const Recipients = (props) => {
  const { recipientType, title, location } = props
  const [{ getRecipientsData = {} }, getRecipients] =
    useGetRecipients()

  const [
    { importRecipientsData = {} },
    importRecipients
  ] = useImportRecipients()
  const [
    { exportRecipientsData = [] },
    exportRecipients
  ] = useExportRecipients()

  const [{ addRecipientsData }, addRecipients] =
    useAddRecipients()
  const [{ removeRecipientsData }, removeRecipients] =
    useRemoveRecipients()
  const [{ getNotificationTypeData = [] }, getNotificationTypeRequest] =
    useGetNotificationType()
  const [showAddModal, setAddModalValue] = useState(false)
  const [resetState] = useResetState()
  const [
    {
      GET_RECIPIENTS_LOADER,
      ADD_RECIPIENTS_LOADER,
      REMOVE_RECIPIENTS_LOADER,
      EXPORT_RECIPIENTS_LOADER,
      IMPORT_RECIPIENTS_LOADER
    }
  ] = useLoaderContextValue()

  const [{
    getRecipientsStatus,
    getNotificationTypeStatus,
    GET_RECIPIENTS_ERROR,
    GET_NOTIFICATION_TYPE_ERROR,
    addRecipientsStatus,
    ADD_RECIPIENTS_ERROR,
    removeRecipientsStatus,
    REMOVE_RECIPIENTS_ERROR,
    exportRecipientsStatus,
    EXPORT_RECIPIENTS_ERROR,
    addRecipientsErrorData,
    removeRecipientsErrorData,
    importRecipientsStatus,
    importRecipientsErrorData,
    IMPORT_RECIPIENTS_ERROR,
    exportRecipientsErrorData
  }, dispatchError] = useErrorContextValue()
  useEffect(() => {
    getNotificationTypeRequest()
    return () => resetState(['getRecipientsData'])
  }, [])

  const getTableData = useCallback(() => {
    const oldSearch = QueryString.parse(location?.search)
    getRecipients({
      query: {
        ...oldSearch,
        recipient_type: recipientType,
        page: 1,
        page_size: 10
      }
    })
  }, [getRecipients])

  // Error handling notify error status
  useEffect(() => {
    if (GET_RECIPIENTS_ERROR) {
      getRecipientsStatus &&
        notification.error({ message: getRecipientsStatus })
      dispatchError(
        resetError({
          GET_RECIPIENTS_ERROR: false,
          getRecipientsStatus: ''
        })
      )
    } else if (GET_NOTIFICATION_TYPE_ERROR) {
      getNotificationTypeStatus &&
        notification.error({ message: getNotificationTypeStatus })
      dispatchError(
        resetError({
          GET_NOTIFICATION_TYPE_ERROR: false,
          getNotificationTypeStatus: ''
        })
      )
    } else if (ADD_RECIPIENTS_ERROR) {
      addRecipientsErrorData?.message &&
        notification.error({ message: addRecipientsErrorData?.message })
      dispatchError(
        resetError({
          ADD_RECIPIENTS_ERROR: false,
          addRecipientsStatus: '',
          addRecipientsErrorData: ''
        })
      )
    } else if (
      !ADD_RECIPIENTS_ERROR &&
      addRecipientsStatus === 'success'
    ) {
      addRecipientsData?.message &&
        notification.success({ message: addRecipientsData?.message })
      dispatchError(
        resetError({
          addRecipientsStatus: ''
        })
      )
      setAddModalValue(false)
      getTableData()
    } else if (REMOVE_RECIPIENTS_ERROR) {
      removeRecipientsErrorData?.message &&
        notification.error({ message: removeRecipientsErrorData?.message })
      dispatchError(
        resetError({
          REMOVE_RECIPIENTS_ERROR: false,
          removeRecipientsStatus: '',
          removeRecipientsErrorData: ''
        })
      )
    } else if (
      !REMOVE_RECIPIENTS_ERROR &&
      removeRecipientsStatus === 'success'
    ) {
      removeRecipientsData?.message &&
        notification.success({ message: removeRecipientsData?.message })
      dispatchError(
        resetError({
          removeRecipientsStatus: ''
        })
      )
      getTableData()
    } else if (EXPORT_RECIPIENTS_ERROR) {
      exportRecipientsErrorData?.message &&
        notification.error({ message: exportRecipientsErrorData?.message })
      dispatchError(
        resetError({
          EXPORT_RECIPIENTS_ERROR: false,
          exportRecipientsStatus: ''
        })
      )
    } else if (
      !EXPORT_RECIPIENTS_ERROR &&
      exportRecipientsStatus === 'success'
    ) {
      exportRecipientsData?.message &&
        notification.success({
          message: exportRecipientsData?.message
        })
      dispatchError(
        resetError({
          exportRecipientsStatus: ''
        })
      )
      fileDownload(
        JSON.stringify(exportRecipientsData?.data),
        `${recipientType}Recipients.json`
      )
    } else if (IMPORT_RECIPIENTS_ERROR) {
      if (importRecipientsErrorData?.message) {
        notification.error({
          message: importRecipientsErrorData?.message
        })
      } else if (importRecipientsErrorData?.error) {
        notification.error({
          message: importRecipientsErrorData?.error
        })
      }
      dispatchError(
        resetError({
          IMPORT_RECIPIENTS_ERROR: false,
          importRecipientsStatus: '',
          importRecipientsErrorData: {}
        })
      )
    } else if (
      !IMPORT_RECIPIENTS_ERROR &&
      importRecipientsStatus === 'success'
    ) {
      importRecipientsData?.message &&
        notification.success({
          message: importRecipientsData?.message
        })

      getTableData()
      dispatchError(
        resetError({
          importRecipientsStatus: ''
        })
      )
    }
  }, [
    GET_RECIPIENTS_ERROR,
    GET_NOTIFICATION_TYPE_ERROR,
    ADD_RECIPIENTS_ERROR,
    addRecipientsErrorData,
    addRecipientsData,
    REMOVE_RECIPIENTS_ERROR,
    EXPORT_RECIPIENTS_ERROR,
    removeRecipientsData,
    exportRecipientsData,
    exportRecipientsErrorData,
    exportRecipientsStatus,
    removeRecipientsStatus,
    addRecipientsStatus,
    getRecipientsStatus,
    getNotificationTypeStatus,
    removeRecipientsErrorData,
    importRecipientsStatus,
    importRecipientsErrorData,
    IMPORT_RECIPIENTS_ERROR,
    importRecipientsData
  ])

  return (
    <>
      {showAddModal && (
        <Modal
          show={showAddModal}
          toggleAddModal={setAddModalValue}
          notificationTypeData={
            getNotificationTypeData || []
          }
          addRecipients={addRecipients}
          loading={!!ADD_RECIPIENTS_LOADER}
          recipientType={recipientType}
        />
      )}
      <CommonTable
        tableData={getRecipientsData}
        getTabledataRequest={getRecipients}
        toggleAddModal={setAddModalValue}
        loader={
          !!(
            GET_RECIPIENTS_LOADER ||
            REMOVE_RECIPIENTS_LOADER ||
            EXPORT_RECIPIENTS_LOADER
          )
        }
        notificationTypeData={getNotificationTypeData}
        title={title}
        removeRecipients={removeRecipients}
        importRecipients={importRecipients}
        exportRecipients={exportRecipients}
        importingFileLoader={!!IMPORT_RECIPIENTS_LOADER}
        recipientType={recipientType}
        {...props}
      />
    </>
  )
}

export default Recipients
