/* eslint-disable react-hooks/exhaustive-deps */
import { Modal, Form, Select, Row, Input, Button } from 'antd'
import React, { useCallback } from 'react'
import { ModalWrapper } from './style'
import { emailRegExp, phoneRegExp } from '../../../../constants/validation-regex'

const FormItem = Form.Item
const { Option } = Select
const { TextArea } = Input

const AddRecipientModal = ({
  form,
  show,
  toggleAddModal,
  notificationTypeData = [],
  addRecipients,
  loading,
  recipientType
}) => {
  const { getFieldDecorator } = form

  const validateForm = useCallback(async () => {
    return new Promise((resolve) => {
      form.validateFields((error, values) => {
        resolve(!error)
      })
    })
  }, [form])

  const onSubmit = useCallback(
    async (e) => {
      e.preventDefault()
      const values = form.getFieldsValue()
      const valid = await validateForm()
      if (valid) {
        addRecipients &&
          addRecipients({
            query: { recipient_type: recipientType },
            body: {
              reason: values.reason,
              recipient: values.recipient,
              notification_type: values.notificationType
            }
          })
      }
    },
    [form]
  )
  const notificationType = form.getFieldValue('notificationType')
  return (
    <Modal
      visible={show}
      okText='Save'
      onCancel={() => toggleAddModal(false)}
      title='Add Receipients'
      maskClosable={false}
      width='50%'
      footer={null}
    >
      <ModalWrapper>
        <Form onSubmit={onSubmit}>
          <Row type='flex' align='middle' className='row'>
            <h4 className='label'>
              <b>Notification Type: </b>
            </h4>
            <FormItem className='form-item'>
              {getFieldDecorator('notificationType', {
                rules: [
                  { required: true, message: 'Please select notification Type' }
                ]
              })(
                <Select placeholder='Notification Type'>
                  {notificationTypeData.map((val) => (
                    <Option key={val} value={val}>
                      {val}
                    </Option>
                  ))}
                </Select>
              )}
            </FormItem>
          </Row>
          <Row type='flex' align='middle' className='row'>
            <h4 className='label'>
              <b>Recipients : </b>
            </h4>
            <FormItem className='form-item'>
              {getFieldDecorator('recipient', {
                rules: [
                  {
                    required: true,
                    pattern:
                      notificationType === 'sms' ||
                      notificationType === 'whatsapp'
                        ? phoneRegExp
                        : emailRegExp,
                    message:
                      notificationType === 'email'
                        ? 'Please enter valid email'
                        : notificationType === 'sms' ||
                          notificationType === 'whatsapp'
                          ? 'Please enter valid phone'
                          : 'Recepients should be email or phone no'
                  }
                ]
              })(<Input placeholder='Recipients' />)}
            </FormItem>
          </Row>
          <Row type='flex' align='middle' className='row'>
            <h4 className='label'>
              <b>Reason : </b>
            </h4>
            <FormItem className='form-item'>
              {getFieldDecorator('reason', {
                rules: [{ required: true, message: 'Please add a reason' }]
              })(<TextArea placeholder='Add a reason' />)}
            </FormItem>
          </Row>
          <Row type='flex' justify='end'>
            <Button type='primary button' onClick={() => toggleAddModal(false)}>
              Cancel
            </Button>
            <Button type='primary button' htmlType='submit' loading={loading}>
              Save
            </Button>
          </Row>
        </Form>
      </ModalWrapper>
    </Modal>
  )
}

export default Form.create({})(AddRecipientModal)
