import { useServiceRequest } from '@pasarpolis/common-react-hooks'

import { useRecipientContextValue } from '../../context'
import { RECIPIENTS } from '../actions'

export const useRecipientsServiceCall = (actionsCall = () => {}) => {
  const [recipientsState, dispatch] = useRecipientContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const request = async (payload = {}) => {
    await callApi(actionsCall({
      ...payload
    }))
  }

  return [recipientsState, request]
}

export const useGetRecipients = () => {
  return useRecipientsServiceCall(RECIPIENTS.getRecipients)
}

export const useGetNotificationType = () => {
  return useRecipientsServiceCall(RECIPIENTS.getNotificationType)
}

export const useAddRecipients = () => {
  return useRecipientsServiceCall(RECIPIENTS.addRecipients)
}

export const useRemoveRecipients = () => {
  return useRecipientsServiceCall(RECIPIENTS.removeRecipients)
}

export const useImportRecipients = () => {
  return useRecipientsServiceCall(RECIPIENTS.importRecipients)
}

export const useExportRecipients = () => {
  return useRecipientsServiceCall(RECIPIENTS.exportRecipients)
}

export const useResetState = () => {
  const [, dispatch] = useRecipientContextValue()
  const resetState = (keys = []) => {
    dispatch(RECIPIENTS.resetReduxStateRecipients(keys))
  }
  return [resetState]
}
