import { RECIPIENTS } from './actions'

export const INITIAL_STATE = {}
const reducers = (state, action) => {
  const { payload } = action

  switch (action.type) {
    case RECIPIENTS.GET_RECIPIENTS:
    case RECIPIENTS.ADD_RECIPIENTS:
    case RECIPIENTS.REMOVE_RECIPIENTS:
    case RECIPIENTS.IMPORT_RECIPIENTS:
    case RECIPIENTS.EXPORT_RECIPIENTS:
    case RECIPIENTS.GET_NOTIFICATION_TYPE:
      return { ...state, ...payload }
    case RECIPIENTS.RESET_REDUX_STATE_RECIPIENTS:
      if (payload && Array.isArray(payload)) {
        const stateToBeReset = {}
        payload.forEach((key) => {
          stateToBeReset[key] = INITIAL_STATE[key]
        })
        return {
          ...state,
          ...stateToBeReset
        }
      } else {
        return {
          ...state
        }
      }
    default:
      return state
  }
}

export default reducers
