import urls from '../../../../config/urls'
const configUrl = urls.url

export const RECIPIENTS = {

  GET_RECIPIENTS: 'GET_RECIPIENTS',
  GET_RECIPIENTS_REQUEST: 'GET_RECIPIENTS_REQUEST',

  GET_NOTIFICATION_TYPE: 'GET_NOTIFICATION_TYPE',
  GET_NOTIFICATION_TYPE_REQUEST: 'GET_NOTIFICATION_TYPE_REQUEST',

  ADD_RECIPIENTS: 'ADD_RECIPIENTS',
  ADD_RECIPIENTS_REQUEST: 'ADD_RECIPIENTS_REQUEST',

  REMOVE_RECIPIENTS: 'REMOVE_RECIPIENTS',
  REMOVE_RECIPIENTS_REQUEST: 'REMOVE_RECIPIENTS_REQUEST',

  IMPORT_RECIPIENTS: 'IMPORT_RECIPIENTS',
  IMPORT_RECIPIENTS_REQUEST: 'IMPORT_RECIPIENTS_REQUEST',

  EXPORT_RECIPIENTS: 'EXPORT_RECIPIENTS',
  EXPORT_RECIPIENTS_REQUEST: 'EXPORT_RECIPIENTS_REQUEST',

  RESET_REDUX_STATE_RECIPIENTS: 'RESET_REDUX_STATE_RECIPIENTS',

  getRecipients: payload => ({
    type: RECIPIENTS.GET_RECIPIENTS_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: configUrl.getRecipientsApi
    }
  }),
  getNotificationType: payload => ({
    type: RECIPIENTS.GET_NOTIFICATION_TYPE,
    payload: {
      ...payload,
      method: 'get',
      url: configUrl.getNotificationTypeLogApi
    }
  }),
  addRecipients: payload => ({
    type: RECIPIENTS.ADD_RECIPIENTS_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: configUrl.addRecipientsApi
    }
  }),
  removeRecipients: payload => ({
    type: RECIPIENTS.REMOVE_RECIPIENTS_REQUEST,
    payload: {
      ...payload,
      method: 'delete',
      url: configUrl.removeRecipientsApi
    }
  }),
  importRecipients: payload => ({
    type: RECIPIENTS.IMPORT_RECIPIENTS_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: configUrl.importRecipientsApi
    }
  }),
  exportRecipients: payload => ({
    type: RECIPIENTS.EXPORT_RECIPIENTS_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: configUrl.exportRecipientsApi
    }
  }),
  resetReduxStateRecipients: keys => ({
    type: RECIPIENTS.RESET_REDUX_STATE_RECIPIENTS,
    payload: keys
  })
}
