/* eslint-disable react-hooks/exhaustive-deps */
import React, { useState, useEffect } from 'react'
import {
  Spin,
  Button,
  Icon,
  Row,
  Col,
  // Upload,
  Tag,
  // message,
  Table
} from 'antd'
import QueryString from 'query-string'

import {
  FilterSelectOption,
  FilterInput
} from '../../../../components/tables/helperCells'
import LayoutContent from '../../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../../components/utility/layoutWrapper'
import WhiteListedWrapper from './style'
import QuerySearchBuilder from '../../../../helpers/querySearchBuilder'

// const dummyRequest = ({ file, onSuccess }) => {
//   onSuccess()
// }

const WhiteListed = ({
  location,
  history,
  tableData,
  getTabledataRequest,
  toggleAddModal,
  notificationTypeData,
  title,
  loader = false,
  removeRecipients,
  // importRecipients,
  // exportRecipients,
  // importingFileLoader,
  recipientType
}) => {
  const [filterNotificationType, setFilterNotificationType] = useState(false)
  const [filterRecipients, setFilterRecipients] = useState(false)
  const [searchTextQuery, setSearchTextQuery] = useState({})
  const [appliedFilter, setAppliedFilter] = useState({})
  // const [selectCheckBox, setSelectCheckBox] = useState([])

  useEffect(() => {
    const querySearch = QueryString.parse(location?.search)
    const { notification_type: notificationType, recipient } = querySearch
    fetch(querySearch)
    setSearchTextQuery({
      notificationType,
      recipient
    })
    setAppliedFilter({
      notificationType,
      recipient
    })
  }, [])

  const renderTitle = (titleClass, text) => {
    return (
      <div className={titleClass}>
        <span>{text}</span>
      </div>
    )
  }

  const onInputChange = (value, identifier) => {
    setSearchTextQuery({
      ...searchTextQuery,
      [identifier]: value
    })
  }

  // const downloadExcel = () => {
  //   if (selectCheckBox.length < 1) {
  //     message.error('select recipients to export')
  //     return
  //   }

  //   exportRecipients({
  //     query: { ids: selectCheckBox, recipient_type: recipientType }
  //   })
  // }

  // const onRowSelected = (selectedRowKeys, selectedRows) => {
  //   const selectedRowsId = selectedRows.map((rowData) => rowData.id)
  //   setSelectCheckBox(selectedRowsId)
  // }
  // const handleChange = async (info) => {
  //   const files = info.file.originFileObj
  //   const reader = new FileReader()

  //   reader.onload = (e) => {
  //     const data = JSON.parse(e.target.result)

  //     !importingFileLoader &&
  //       importRecipients({
  //         query: {
  //           recipient_type: recipientType
  //         },
  //         body: data
  //       })
  //   }
  //   reader.readAsText(files)
  // }

  const onSearch = (e, key) => {
    e.preventDefault()
    const searchText = {}
    searchText.recipient = searchTextQuery.recipient
    searchText.notification_type = searchTextQuery.notificationType
    const search = QuerySearchBuilder(searchText)
    history.push({ pathname: location?.pathname, search })
    fetch(searchText)
    setFilterNotificationType(false)
    setFilterRecipients(false)
    setAppliedFilter(searchTextQuery)
  }

  const renderIcon = (active, type) => {
    let iconClass = 'filter-icon'
    if (active) {
      iconClass += ' active'
    }
    return <Icon className={iconClass} type={type} theme='outlined' />
  }

  const columns = [
    {
      key: 'id',
      title: renderTitle('title-without-margin', 'Id'),
      dataIndex: 'id'
    },
    {
      key: 'notification_type',
      title: renderTitle('title-without-margin', 'Notification Type'),
      dataIndex: 'notification_type',
      filterDropdown: (
        <FilterSelectOption
          searchText={
            searchTextQuery.notificationType
              ? searchTextQuery.notificationType
              : undefined
          }
          onInputChange={(e) =>
            onInputChange(e.target.value, 'notificationType')}
          onSearch={(e) => onSearch(e, 'notificationType')}
          optionData={notificationTypeData || []}
          renderOption={(data) => {
            return data.map((val) => (
              <option key={val} value={val}>
                {val}
              </option>
            ))
          }}
        />
      ),
      filterIcon: renderIcon(!!searchTextQuery.notification_type, 'filter'),
      filterDropdownVisible: filterNotificationType,
      onFilterDropdownVisibleChange: (visible) =>
        setFilterNotificationType(visible)
    },
    {
      key: 'recipient',
      title: renderTitle('title-with-margin', 'Recipient'),
      dataIndex: 'recipient',
      filterDropdown: (
        <FilterInput
          idIdentifier='recipient'
          searchText={searchTextQuery.recipient}
          onInputChange={(e) => onInputChange(e.target.value, 'recipient')}
          onSearch={(e) => onSearch(e, 'recipient')}
        />
      ),
      filterIcon: renderIcon(!!searchTextQuery.recipient, 'search'),
      filterDropdownVisible: filterRecipients,
      onFilterDropdownVisibleChange: (visible) => setFilterRecipients(visible)
    },
    {
      key: 'Reason',
      title: renderTitle('title-with-margin', 'Reason'),
      dataIndex: 'reason'
    },
    {
      key: 'added_by',
      title: renderTitle('title-with-margin', 'Added By'),
      dataIndex: 'author'
    },
    {
      key: 'created_at',
      title: renderTitle('title-with-margin', 'Created At'),
      dataIndex: 'created_at'
    },
    {
      key: 'action',
      title: renderTitle('title-with-margin', 'Action'),
      render: (row) => (
        !row.is_default && (
          <div
            className='edit-button'
            onClick={() => {
              removeRecipients({
                query: { recipient_type: recipientType },
                body: {
                  recipient: row.recipient,
                  notification_type: row.notification_type
                }
              })
            }}
          >
            Remove
          </div>
        )
      )
    }
  ]

  const clearFilter = (identifier) => {
    setSearchTextQuery({
      ...searchTextQuery,
      [identifier]: undefined
    })
    setAppliedFilter({
      ...appliedFilter,
      [identifier]: undefined
    })

    const oldSearch = QueryString.parse(location?.search)
    if (identifier === 'notificationType') {
      delete oldSearch.notification_type
    } else {
      delete oldSearch[identifier]
    }
    const search = QuerySearchBuilder(oldSearch)
    history.push({ pathname: location?.pathname, search })
    fetch(oldSearch)
  }

  const fetch = (params = {}) => {
    const { page } = params
    const pageNumber = Number(page) || 1
    delete params.page

    getTabledataRequest({
      query: {
        ...params,
        recipient_type: recipientType,
        page: pageNumber,
        page_size: 10
      }
    })
  }

  const handlePageChange = (val) => {
    const { current } = val
    const querySearch = QueryString.parse(location?.search)
    const searchText = { ...querySearch }
    searchText.page = current
    const search = QuerySearchBuilder(searchText)
    history.push({ pathname: location?.pathname, search })
    fetch(searchText)
  }
  return (
    <LayoutContentWrapper className='referral-table'>
      <LayoutContent>
        <WhiteListedWrapper>
          <Row align='middle' type='flex'>
            <Col xs={{ span: 24 }} md={{ span: 10 }} xl={{ span: 16 }}>
              <h2>
                <b>{title}</b>
              </h2>
            </Col>
            <Col xs={{ span: 8 }} md={{ span: 4 }} xl={{ span: 2 }}>
              {/* <Upload
                name='avatar'
                showUploadList={false}
                multiple={false}
                customRequest={dummyRequest}
                onChange={(file) => handleChange(file)}
              >
                <Button className='form-submit' type='primary'>
                  <Icon type='upload' />
                  Import
                </Button>
              </Upload> */}
            </Col>
            <Col xs={{ span: 8 }} md={{ span: 4 }} xl={{ span: 2 }}>
              {/* <Button
                className='form-submit'
                type='primary'
                onClick={downloadExcel}
              >
                Export
              </Button> */}
            </Col>
            <Col xs={{ span: 8 }} md={{ span: 6 }} xl={{ span: 4 }}>
              <Button
                className='form-submit'
                type='primary'
                onClick={() => toggleAddModal(true)}
              >
                Add New Recipient
              </Button>
            </Col>
          </Row>
          {Object.keys(appliedFilter).map(
            (key) =>
              appliedFilter[key] && (
                <Tag
                  className='search-tag'
                  key={key}
                  color='purple'
                  closable='closable'
                  onClose={() => clearFilter(key)}
                >
                  {key} : {appliedFilter[key]}
                </Tag>
              )
          )}
          <Spin spinning={loader}>
            <Table
              columns={columns}
              rowKey={(record) => record.reference_id}
              dataSource={tableData.data}
              pagination={{
                pageSize: Number(tableData?.meta_data?.limit),
                total: Number(tableData?.meta_data?.total),
                current: Number(tableData?.meta_data?.page)
              }}
              // rowSelection={{
              //   type: 'checkbox',
              //   onChange: onRowSelected
              // }}
              onChange={handlePageChange}
            />
          </Spin>
        </WhiteListedWrapper>
      </LayoutContent>
    </LayoutContentWrapper>
  )
}

export default WhiteListed
